const markRuntimeInstanceReady = `-- name: MarkRuntimeInstanceReady :one
WITH RECURSIVE restore_secret_authority AS MATERIALIZED (
    SELECT runtime_instances.id AS runtime_instance_id,
           workspace_secrets.placement_kind,
           workspace_secrets.placement_target
      FROM runtime_instances
      JOIN workspace_secrets
        ON workspace_secrets.workspace_id = runtime_instances.workspace_id
      JOIN secrets
        ON secrets.id = workspace_secrets.secret_id
       AND secrets.status = 'active'
      JOIN secret_resolutions
        ON secret_resolutions.workspace_id = workspace_secrets.workspace_id
       AND secret_resolutions.run_id = runtime_instances.reserved_run_id
       AND secret_resolutions.attempt_number = runtime_instances.reserved_attempt_number
       AND secret_resolutions.placement_kind = workspace_secrets.placement_kind
       AND secret_resolutions.placement_target = workspace_secrets.placement_target
       AND secret_resolutions.secret_id = workspace_secrets.secret_id
       AND secret_resolutions.revocation_generation = secrets.revocation_generation
     WHERE runtime_instances.id = $4
       AND runtime_instances.worker_instance_id = $5
       AND runtime_instances.worker_epoch = $6
       AND runtime_instances.restore_checkpoint_id IS NOT NULL
     ORDER BY secrets.id, workspace_secrets.placement_kind, workspace_secrets.placement_target
     FOR UPDATE OF secrets
), restore_actor_authority AS MATERIALIZED (
    SELECT runtime_instances.id AS runtime_instance_id,
           sessions.id AS session_id,
           sessions.committed_input_sequence,
           sessions.next_input_sequence
      FROM runtime_instances
      JOIN runs
        ON runs.id = runtime_instances.reserved_run_id
       AND runs.entrypoint_kind = 'actor'
       AND runs.session_id IS NOT NULL
      JOIN sessions
        ON sessions.id = runs.session_id
       AND sessions.workspace_id = runtime_instances.workspace_id
       AND sessions.current_run_id = runs.id
       AND sessions.status IN ('open', 'closing')
     WHERE runtime_instances.id = $4
       AND runtime_instances.worker_instance_id = $5
       AND runtime_instances.worker_epoch = $6
       AND runtime_instances.restore_checkpoint_id IS NOT NULL
       AND (SELECT count(*) FROM restore_secret_authority) >= 0
     FOR UPDATE OF sessions
), restore_entrypoint_authority AS MATERIALIZED (
    SELECT runtime_instances.id AS runtime_instance_id,
           NULL::uuid AS session_id,
           NULL::bigint AS committed_input_sequence,
           NULL::bigint AS next_input_sequence
      FROM runtime_instances
      JOIN runs ON runs.id = runtime_instances.reserved_run_id
     WHERE runtime_instances.id = $4
       AND runtime_instances.worker_instance_id = $5
       AND runtime_instances.worker_epoch = $6
       AND runtime_instances.restore_checkpoint_id IS NOT NULL
       AND runs.entrypoint_kind = 'task'
       AND runs.session_id IS NULL
       AND (SELECT count(*) FROM restore_secret_authority) >= 0
    UNION ALL
    SELECT restore_actor_authority.runtime_instance_id, restore_actor_authority.session_id, restore_actor_authority.committed_input_sequence, restore_actor_authority.next_input_sequence FROM restore_actor_authority
), restore_run_authority AS MATERIALIZED (
    SELECT runtime_instances.id AS runtime_instance_id,
           restore_entrypoint_authority.session_id,
           restore_entrypoint_authority.committed_input_sequence,
           restore_entrypoint_authority.next_input_sequence,
           runs.entrypoint_kind,
           runs.session_input_start_sequence,
           runs.session_input_high_watermark
      FROM restore_entrypoint_authority
      JOIN runtime_instances
        ON runtime_instances.id = restore_entrypoint_authority.runtime_instance_id
      JOIN runs
        ON runs.id = runtime_instances.reserved_run_id
       AND runs.org_id = runtime_instances.org_id
       AND runs.project_id = runtime_instances.project_id
       AND runs.environment_id = runtime_instances.environment_id
       AND runs.workspace_id = runtime_instances.workspace_id
       AND runs.current_attempt_number = runtime_instances.reserved_attempt_number
       AND runs.status = 'queued'
       AND runs.current_run_lease_id IS NULL
       AND ((runs.entrypoint_kind = 'task'
             AND runs.session_id IS NULL
             AND restore_entrypoint_authority.session_id IS NULL)
            OR (runs.entrypoint_kind = 'actor'
                AND runs.session_id = restore_entrypoint_authority.session_id
                AND runs.cause_kind IN ('actor_start', 'continuation')
                AND runs.parent_run_id IS NULL))
     FOR UPDATE OF runs
), restore_same_workspace_ancestors AS (
    SELECT runtime_instances.id AS runtime_instance_id,
           parent.id AS parent_run_id,
           parent.environment_id,
           parent.parent_run_id AS next_parent_run_id,
           parent.parent_owns_lifecycle,
           parent.session_id AS parent_session_id,
           edge.ownership_generation,
           edge.parent_writer_generation
      FROM restore_run_authority
      JOIN runtime_instances
        ON runtime_instances.id = restore_run_authority.runtime_instance_id
      JOIN run_waits AS edge
        ON edge.child_run_id = runtime_instances.reserved_run_id
       AND edge.workspace_id = runtime_instances.workspace_id
       AND edge.kind = 'child'
       AND EXISTS (
           SELECT 1 FROM runs AS owned_child
            WHERE owned_child.id = edge.child_run_id
              AND owned_child.parent_run_id = edge.run_id
              AND owned_child.environment_id = edge.environment_id
              AND owned_child.parent_owns_lifecycle IS TRUE
       )
       AND edge.condition_status = 'pending'
       AND edge.suspension_status = 'parked'
       AND edge.ownership_generation IS NOT NULL
       AND edge.parent_writer_generation IS NOT NULL
       AND edge.child_writer_generation IS NOT NULL
       AND edge.resume_writer_generation IS NULL
      JOIN runs AS parent
        ON parent.environment_id = edge.environment_id
       AND parent.id = edge.run_id
       AND parent.workspace_id = edge.workspace_id
       AND parent.status = 'waiting'
       AND parent.current_run_lease_id IS NULL
    UNION ALL
    SELECT child.runtime_instance_id,
           parent.id,
           parent.environment_id,
           parent.parent_run_id,
           parent.parent_owns_lifecycle,
           parent.session_id,
           edge.ownership_generation,
           edge.parent_writer_generation
      FROM restore_same_workspace_ancestors AS child
      JOIN run_waits AS edge
        ON edge.child_run_id = child.parent_run_id
       AND edge.kind = 'child'
       AND edge.run_id = child.next_parent_run_id
       AND edge.environment_id = child.environment_id
       AND edge.condition_status = 'pending'
       AND edge.suspension_status = 'parked'
       AND edge.ownership_generation = child.ownership_generation
       AND edge.child_writer_generation = child.parent_writer_generation
       AND edge.resume_writer_generation IS NULL
      JOIN runs AS parent
        ON parent.environment_id = edge.environment_id
       AND parent.id = edge.run_id
       AND parent.workspace_id = edge.workspace_id
       AND parent.status = 'waiting'
       AND parent.current_run_lease_id IS NULL
     WHERE child.parent_owns_lifecycle IS TRUE
), restore_same_workspace_root_authority AS MATERIALIZED (
    SELECT ancestors.runtime_instance_id,
           ancestors.parent_run_id,
           ancestors.parent_session_id,
           ancestors.ownership_generation
      FROM restore_same_workspace_ancestors AS ancestors
     WHERE (ancestors.next_parent_run_id IS NULL
            OR ancestors.parent_owns_lifecycle IS NOT TRUE)
), restore_workspace_authority AS MATERIALIZED (
    SELECT restore_run_authority.runtime_instance_id, restore_run_authority.session_id, restore_run_authority.committed_input_sequence, restore_run_authority.next_input_sequence, restore_run_authority.entrypoint_kind, restore_run_authority.session_input_start_sequence, restore_run_authority.session_input_high_watermark
      FROM restore_run_authority
      JOIN runtime_instances
        ON runtime_instances.id = restore_run_authority.runtime_instance_id
      JOIN computers
        ON computers.id = runtime_instances.workspace_id
       AND computers.environment_id = runtime_instances.environment_id
       AND ((restore_run_authority.entrypoint_kind = 'task'
             AND (
                 (computers.owner_run_id = runtime_instances.reserved_run_id
                  AND computers.owner_session_id IS NULL)
                 OR EXISTS (
                     SELECT 1
                       FROM restore_same_workspace_root_authority AS root
                      WHERE root.runtime_instance_id = runtime_instances.id
                        AND root.ownership_generation = computers.ownership_generation
                        AND ((root.parent_session_id IS NULL
                              AND computers.owner_run_id = root.parent_run_id
                              AND computers.owner_session_id IS NULL)
                             OR (root.parent_session_id IS NOT NULL
                                 AND computers.owner_session_id = root.parent_session_id
                                 AND computers.owner_run_id IS NULL))
                 )
             ))
            OR (restore_run_authority.entrypoint_kind = 'actor'
                AND computers.owner_session_id = restore_run_authority.session_id
                AND computers.owner_run_id IS NULL))
       AND computers.status = 'active'
       AND computers.desired_state = 'active'
       AND computers.dirty_state = 'clean'
     FOR UPDATE OF computers
), restore_attempt_authority AS MATERIALIZED (
    SELECT restore_workspace_authority.runtime_instance_id, restore_workspace_authority.session_id, restore_workspace_authority.committed_input_sequence, restore_workspace_authority.next_input_sequence, restore_workspace_authority.entrypoint_kind, restore_workspace_authority.session_input_start_sequence, restore_workspace_authority.session_input_high_watermark
      FROM restore_workspace_authority
      JOIN runtime_instances
        ON runtime_instances.id = restore_workspace_authority.runtime_instance_id
      JOIN run_attempts
        ON run_attempts.run_id = runtime_instances.reserved_run_id
       AND run_attempts.number = runtime_instances.reserved_attempt_number
       AND run_attempts.workspace_id = runtime_instances.workspace_id
       AND run_attempts.entrypoint_kind = restore_workspace_authority.entrypoint_kind
       AND run_attempts.terminal_at IS NULL
       AND (restore_workspace_authority.entrypoint_kind = 'task'
            OR (run_attempts.session_input_start_sequence IS NOT NULL
                AND run_attempts.session_input_start_sequence = restore_workspace_authority.session_input_start_sequence
                AND restore_workspace_authority.session_input_start_sequence
                    <= restore_workspace_authority.session_input_high_watermark
                AND restore_workspace_authority.session_input_start_sequence
                    <= restore_workspace_authority.committed_input_sequence
                AND restore_workspace_authority.committed_input_sequence
                    < restore_workspace_authority.next_input_sequence))
     FOR UPDATE OF run_attempts
), substrate_authority AS MATERIALIZED (
    SELECT runtime_instances.id AS runtime_instance_id
      FROM runtime_instances
      JOIN worker_instances
        ON worker_instances.id = runtime_instances.worker_instance_id
	   AND worker_instances.worker_group_id = runtime_instances.worker_group_id
	   AND worker_instances.current_epoch = runtime_instances.worker_epoch
	   AND worker_instances.status IN ('active', 'draining')
      JOIN runtime_substrates
        ON runtime_substrates.id = $1
       AND runtime_substrates.org_id = runtime_instances.org_id
       AND runtime_substrates.project_id = runtime_instances.project_id
       AND runtime_substrates.environment_id = runtime_instances.environment_id
       AND runtime_substrates.deployment_definition_id = runtime_instances.deployment_definition_id
       AND runtime_substrates.substrate_format = worker_instances.substrate_format
       AND runtime_substrates.substrate_contract = worker_instances.substrate_contract
     WHERE runtime_instances.id = $4
       AND runtime_instances.worker_instance_id = $5
       AND runtime_instances.worker_epoch = $6
       AND (SELECT count(*) FROM restore_secret_authority) >= 0
       AND (runtime_instances.restore_checkpoint_id IS NULL
            OR EXISTS (
                SELECT 1
                  FROM restore_attempt_authority
                 WHERE restore_attempt_authority.runtime_instance_id = runtime_instances.id
            ))
     ORDER BY worker_instances.id, runtime_substrates.id
     FOR UPDATE OF worker_instances, runtime_substrates
), runtime_authority AS MATERIALIZED (
    SELECT runtime_instances.id AS runtime_instance_id
      FROM substrate_authority
      JOIN runtime_instances
        ON runtime_instances.id = substrate_authority.runtime_instance_id
       AND runtime_instances.worker_instance_id = $5
       AND runtime_instances.worker_epoch = $6
       AND runtime_instances.desired_version = $2
       AND runtime_instances.observed_version = $7
       AND runtime_instances.observed_state = 'allocated'
       AND (runtime_instances.runtime_substrate_id IS NULL
            OR runtime_instances.runtime_substrate_id = $1)
     FOR UPDATE OF runtime_instances
), restore_authority AS MATERIALIZED (
    SELECT runtime_instances.id AS runtime_instance_id,
           run_checkpoints.expires_at AS checkpoint_expires_at
      FROM runtime_authority
      JOIN runtime_instances
        ON runtime_instances.id = runtime_authority.runtime_instance_id
      JOIN restore_attempt_authority
        ON restore_attempt_authority.runtime_instance_id = runtime_instances.id
      JOIN run_waits
        ON run_waits.run_id = runtime_instances.reserved_run_id
       AND run_waits.attempt_number = runtime_instances.reserved_attempt_number
       AND run_waits.workspace_id = runtime_instances.workspace_id
       AND run_waits.suspension_status = 'resume_pending'
       AND run_waits.resume_writer_generation IS NULL
       AND (run_waits.resume_workspace_version_id IS NULL
            OR run_waits.resume_workspace_version_id = runtime_instances.reserved_workspace_version_id)
       AND run_waits.suspend_checkpoint_id = runtime_instances.restore_checkpoint_id
      JOIN run_checkpoints
        ON run_checkpoints.id = runtime_instances.restore_checkpoint_id
       AND run_checkpoints.id = run_waits.suspend_checkpoint_id
       AND run_checkpoints.run_id = runtime_instances.reserved_run_id
       AND run_checkpoints.attempt_number = runtime_instances.reserved_attempt_number
       AND run_checkpoints.run_wait_id = run_waits.id
       AND run_checkpoints.workspace_id = runtime_instances.workspace_id
       AND run_checkpoints.private_workspace_version_id IS NOT NULL
       AND run_checkpoints.status = 'ready'
       AND ((restore_attempt_authority.entrypoint_kind = 'task'
             AND run_checkpoints.actor_speculative_input_sequence IS NULL)
            OR (restore_attempt_authority.entrypoint_kind = 'actor'
                AND run_checkpoints.actor_speculative_input_sequence
                    BETWEEN restore_attempt_authority.committed_input_sequence
                        AND restore_attempt_authority.next_input_sequence - 1))
       AND (run_checkpoints.expires_at IS NULL OR run_checkpoints.expires_at > transaction_timestamp())
      JOIN run_leases AS source_lease
        ON source_lease.id = run_checkpoints.source_run_lease_id
       AND source_lease.run_id = run_checkpoints.run_id
       AND source_lease.attempt_number = run_checkpoints.attempt_number
       AND source_lease.workspace_id = run_checkpoints.workspace_id
       AND source_lease.status = 'checkpointed'
      JOIN runtime_instances AS source_runtime
        ON source_runtime.id = source_lease.runtime_instance_id
       AND source_runtime.runtime_identity_id = runtime_instances.runtime_identity_id
       AND source_runtime.vm_vcpu_count = runtime_instances.vm_vcpu_count
       AND source_runtime.cpu_config_digest = runtime_instances.cpu_config_digest
       AND source_runtime.runtime_substrate_id = $1
      JOIN computer_versions
        ON computer_versions.workspace_id = runtime_instances.workspace_id
       AND computer_versions.id = runtime_instances.reserved_workspace_version_id
       AND computer_versions.status = 'private'
     WHERE runtime_instances.id = $4
       AND runtime_instances.worker_instance_id = $5
       AND runtime_instances.worker_epoch = $6
       AND (SELECT count(*) FROM workspace_secrets
             WHERE workspace_secrets.workspace_id = runtime_instances.workspace_id)
           = (SELECT count(*) FROM restore_secret_authority
               WHERE restore_secret_authority.runtime_instance_id = runtime_instances.id)
     FOR UPDATE OF run_waits, run_checkpoints, computer_versions
), ready_decision AS MATERIALIZED (
    -- Sample time after all preparation/restore row locks, not at transaction
    -- start or while a row-locking SELECT is still waiting for its input.
    SELECT runtime_authority.runtime_instance_id, clock_timestamp() AS decided_at
      FROM runtime_authority
     WHERE (SELECT count(*) FROM restore_authority) >= 0
)
UPDATE runtime_instances
   SET runtime_substrate_id = $1,
       observed_state = 'ready', observed_version = observed_version + 1,
       observed_desired_version = $2, observed_at = ready_decision.decided_at,
       ready_at = COALESCE(ready_at, ready_decision.decided_at),
       reservation_expires_at = CASE WHEN reserved_run_id IS NOT NULL OR reserved_process_id IS NOT NULL
           THEN ready_decision.decided_at + $3::bigint * interval '1 second' END,
       updated_at = ready_decision.decided_at
  FROM ready_decision
 WHERE runtime_instances.id = $4 AND runtime_instances.worker_instance_id = $5
   AND ready_decision.runtime_instance_id = runtime_instances.id
   AND runtime_instances.worker_epoch = $6 AND runtime_instances.desired_version = $2
   AND runtime_instances.observed_version = $7
   AND runtime_instances.observed_state = 'allocated'
   AND runtime_instances.preparation_expires_at > ready_decision.decided_at
   AND EXISTS (
       SELECT 1 FROM computer_versions AS persistent_version
         JOIN computer_version_roots AS retained_root
           ON retained_root.environment_id = persistent_version.environment_id
          AND retained_root.computer_id = persistent_version.workspace_id
          AND retained_root.version_id = persistent_version.id
        WHERE persistent_version.environment_id = runtime_instances.environment_id
          AND persistent_version.workspace_id = runtime_instances.workspace_id
          AND persistent_version.id = runtime_instances.reserved_workspace_version_id
          AND persistent_version.status IN ('committed', 'private')
          AND runtime_instances.retained_computer_source_version_id = persistent_version.id
   )
   AND runtime_instances.vm_vcpu_count = $8
   AND runtime_instances.cpu_config_digest = $9
   AND (runtime_instances.runtime_substrate_id IS NULL
        OR runtime_instances.runtime_substrate_id = $1)
   AND (runtime_instances.restore_checkpoint_id IS NULL
        OR EXISTS (
            SELECT 1 FROM restore_authority
             WHERE restore_authority.runtime_instance_id = runtime_instances.id
               AND (restore_authority.checkpoint_expires_at IS NULL
                    OR restore_authority.checkpoint_expires_at > ready_decision.decided_at)
        ))
RETURNING runtime_instances.id, runtime_instances.org_id, runtime_instances.worker_group_id, runtime_instances.project_id, runtime_instances.environment_id, runtime_instances.region_id, runtime_instances.worker_instance_id, runtime_instances.runtime_identity_id, runtime_instances.deployment_definition_id, runtime_instances.runtime_substrate_id, runtime_instances.worker_epoch, runtime_instances.vm_vcpu_count, runtime_instances.cpu_config_digest, runtime_instances.reserved_cpu_millis, runtime_instances.reserved_memory_bytes, runtime_instances.reserved_guest_ephemeral_disk_bytes, runtime_instances.reserved_execution_slots, runtime_instances.workspace_id, runtime_instances.program_deployment_id, runtime_instances.restore_checkpoint_id, runtime_instances.reserved_run_id, runtime_instances.reserved_attempt_number, runtime_instances.reserved_process_id, runtime_instances.reserved_workspace_version_id, runtime_instances.computer_source_version_id, runtime_instances.computer_save_sequence, runtime_instances.computer_save_id, runtime_instances.computer_save_lease_id, runtime_instances.computer_save_predecessor_id, runtime_instances.retained_computer_source_version_id, runtime_instances.computer_write_key_id, runtime_instances.retained_computer_write_key_id, runtime_instances.computer_key_available, runtime_instances.preparation_expires_at, runtime_instances.reservation_expires_at, runtime_instances.desired_state, runtime_instances.desired_version, runtime_instances.desired_at, runtime_instances.desired_reason, runtime_instances.observed_state, runtime_instances.observed_version, runtime_instances.observed_desired_version, runtime_instances.observed_at, runtime_instances.allocated_at, runtime_instances.ready_at, runtime_instances.terminal_at, runtime_instances.reclaimed_at, runtime_instances.reclaim_evidence, runtime_instances.terminal_reason_code, runtime_instances.terminal_error, runtime_instances.updated_at, runtime_instances.computer_payload_required
`

